from pathlib import Path
import os,json,hashlib,traceback,time
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1];Q=Path(os.environ.get('RF33_QA',str(R/'qa/file')));Q.mkdir(parents=True,exist_ok=True)
URL=os.environ.get('RF33_URL',(R/'preview.html').as_uri());M=json.loads((R/'BUILD_MANIFEST.json').read_text());O=json.loads((R/'runtime-observation.json').read_text())
report={'version':'REALITY-HC-S3.3-A','url':URL,'sourceCommit':M['sourceCommit'],'passed':False,'checks':[],'pageErrors':[],'consoleErrors':[],'failedRequests':[],'physicalDeviceTested':False,'fitCertified':False,'sourceOutcome':O['sourceOutcome']};requests=[]
def save():(Q/'BROWSER.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
def check(name,ok=True,detail=None):
 if not ok:raise AssertionError(name+': '+str(detail))
 report['checks'].append({'name':name,'passed':True,'detail':detail});print('PASS',name,flush=True);save()
def shot(page,name):
 p=Q/(name+'.png');page.screenshot(path=str(p),timeout=60000);report.setdefault('screenshots',[]).append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
with sync_playwright() as pw:
 browser=pw.chromium.launch(headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 context=browser.new_context(viewport={'width':1440,'height':1100},device_scale_factor=1,accept_downloads=True)
 page=context.new_page();page.set_default_timeout(60000)
 page.on('pageerror',lambda e:report['pageErrors'].append(str(e)));page.on('console',lambda e:report['consoleErrors'].append(e.text) if e.type=='error' else None)
 page.on('request',lambda r:requests.append(r.url) if r.url.startswith(('http:','https:')) else None);page.on('requestfailed',lambda r:report['failedRequests'].append({'url':r.url,'failure':r.failure}))
 state=lambda:page.evaluate('__REALITY_S33__.report()')
 def current():return next(x for x in state()['bundle']['objects'] if x['objectId'].endswith('-'+state()['role']))
 def status_of(id):return next(c['status'] for c in current()['checks'] if c['id']==id)
 try:
  started=time.monotonic();page.goto(URL,wait_until='domcontentloaded',timeout=120000);page.wait_for_function('!!window.__REALITY_S33__');report['readyMS']=(time.monotonic()-started)*1000
  check('fresh exact source identity',state()['sourceCommit']==M['sourceCommit'])
  check('only bounded D03 top and bottom present',len(state()['bundle']['objects'])==2 and [p['presetId'] for p in state()['observation']['pieces']]==['T03','P02'])
  check('prephysics and nonlive labels visible','试穿前' in page.locator('#rf33-mode').inner_text() and '非实时' in page.locator('#rf33-mode').inner_text())
  check('no invented presented frame',state()['observation']['capture']['frame'] is None)
  check('original terminal failure or outcome visible',O['sourceOutcome']['statusText'] in page.locator('#rf33-outcome').inner_text())
  check('failed try-on not greenwashed',status_of('fit:captured_runtime')==('FAIL' if O['sourceOutcome']['error'] else 'WARNING'))
  check('matching person identity still separately passes',status_of('person:identity')=='PASS')
  check('explicit proportion missing stays unknown',status_of('person:proportion_revision')=='UNKNOWN')
  check('independent material version not silently adopted',status_of('material:independent_workbench')=='WARNING')
  check('old actual denim R11 donor shown','denim-r11@' in page.locator('#rf33-links').inner_text())
  check('physical and manufacturing axes remain unknown',status_of('axis:physics')=='UNKNOWN' and status_of('axis:manufacturing')=='UNKNOWN')
  check('actual panel boundary shown',bool(page.locator('#rf33-outline path.outline-shape').get_attribute('d')))
  check('no native engine or iframe automatically loaded',state()['legacyFrames']==0 and page.locator('iframe').count()==0)
  base_network=len(requests)
  shot(page,'01-prephysics-relations')
  for role in ['bottom','top']:
   page.locator('[data-role="'+role+'"]').click();check(role+' selection uses matching actual packet',state()['role']==role)
   panels=next(p for p in O['pieces'] if p['role']==role)['panels']
   check(role+' has original panel list',page.locator('#rf33-panel option').count()==len(panels))
   for p in panels:
    page.locator('#rf33-panel').select_option(p['id']);check(role+':'+p['id']+' boundary and axis facts render',state()['panelId']==p['id'] and p['id'] in page.locator('#rf33-outline').text_content() and '× 0.001' in page.locator('#rf33-axis-facts').inner_text())
  page.locator('#rf33-missing').uncheck();check('all-check filter includes valid identities',page.locator('[data-check="person:identity"]').count()==1);page.locator('#rf33-missing').check()
  original=state()['observation'];page.locator('#rf33-bad-person').click()
  check('synthetic person mismatch is detected',status_of('person:identity')=='FAIL' and state()['mode']=='scenario')
  check('synthetic label cannot be mistaken for source finding',page.locator('#rf33-scenario-note').is_visible() and '人工反例' in page.locator('#rf33-mode').inner_text())
  shot(page,'02-conflict-example')
  with page.expect_download() as ev:page.locator('#rf33-export').click()
  path=Q/'SCENARIO_COMMON.json';ev.value.save_as(path);check('exported negative fixture retains scenario label',json.loads(path.read_text())['reviewContext']['scenario'] is True)
  page.locator('#rf33-restore').click();check('restoration recovers exact original observation',state()['observation']==original)
  page.locator('#rf33-bad-axis').click();check('wrong display axis detected',any(c['id'].startswith('axis:') and c['status']=='FAIL' for c in current()['checks']))
  page.locator('#rf33-restore').click();before=state()['observation'];page.locator('#rf33-bad-source').click();check('source mismatch atomically rejected',state()['observation']==before and 'SOURCE_PIN_MISMATCH' in page.locator('#rf33-status').inner_text())
  with page.expect_download() as ev:page.locator('#rf33-export-observation').click()
  export=Q/'OBSERVATION.json';ev.value.save_as(export);packet=json.loads(export.read_text());check('actual observation exported with prepared stage',packet['observation']['capture']['mode']=='native_prephysics_binding_capture')
  with page.expect_download() as ev:page.locator('#rf33-export').click()
  p=Q/'COMMON.json';ev.value.save_as(p);common=json.loads(p.read_text());check('shared object envelope preserved',common['schema']=='kaopu/reality-foundation-bundle@0.2' and common['reviewContext']['live'] is False)
  with page.expect_download() as ev:page.locator('#rf33-export-defects').click()
  p=Q/'DEFECTS.json';ev.value.save_as(p);defs=json.loads(p.read_text());check('defects cannot authorize source repair',defs['defects'] and all(not d['repairAuthorized'] and d['verificationRequired'] for d in defs['defects']))
  bad=json.loads(json.dumps(packet));bad['observation']['pieces'][0]['panels'][0]['paperUnit']='m'
  page.locator('#rf33-file').set_input_files({'name':'invalid-units.json','mimeType':'application/json','buffer':json.dumps(bad).encode()});page.wait_for_function('document.getElementById("rf33-status").textContent.includes("UNIT_MISMATCH")')
  check('invalid imported units preserve effective observation',state()['observation']==before)
  page.locator('#rf33-file').set_input_files(str(export));page.wait_for_function('__REALITY_S33__.report().mode==="imported"')
  check('import stays unverified',all(o['sourceMode']=='imported_unverified' for o in state()['bundle']['objects']) and '未复验' in page.locator('#rf33-mode').inner_text())
  check('imported source failure also not falsely reverified',status_of('fit:captured_runtime')=='UNKNOWN')
  page.locator('#rf33-restore').click();check('restored native outcome still retained',state()['observation']['sourceOutcome']==O['sourceOutcome'])
  check('inspector interactions require no extra HTTP',len(requests)==base_network)
  if URL.startswith('file:'):check('inspector core works fully offline',not requests)
  race=page.evaluate('async()=>{const p=__REALITY_S33__.openLegacy();__REALITY_S33__.closeLegacy();await p;return __REALITY_S33__.report().legacyFrames;}');check('cancelled material-entry load cannot reopen iframe',race==0)
  page.locator('#rf33-legacy-open').click();page.wait_for_function('document.getElementById("rf33-legacy-frame")?.contentWindow.__REALITY_S32__')
  data=page.locator('#rf33-legacy-frame').evaluate('(f)=>f.contentWindow.__REALITY_S32__.connections()')
  check('exact previous three-material registry restored',len(data['registry']['entries'])==3 and all(not x['productionInstalled'] for x in data['registry']['entries']))
  check('legacy entry has all native material buttons',page.frame_locator('#rf33-legacy-frame').locator('#load').count()==1 and page.frame_locator('#rf33-legacy-frame').locator('#load-knit').count()==1 and page.frame_locator('#rf33-legacy-frame').locator('#load-leather').count()==1)
  check('legacy byte identity verified before running',any(e['type']=='legacy-loaded' and e['detail']==M['legacy']['sha256'] for e in state()['events']))
  if URL.startswith('https:'):
   page.frame_locator('#rf33-legacy-frame').locator('#load').click()
   page.wait_for_function('document.getElementById("rf33-legacy-frame").contentWindow.__REALITY_S32__.report().native?.family==="denim"',timeout=120000)
   check('previous real denim still renders and exports',page.locator('#rf33-legacy-frame').evaluate('(f)=>f.contentWindow.__REALITY_S32__.report().native.preservation.passed'))
  page.locator('#rf33-back').click();check('closing material entry releases iframe',state()['legacyFrames']==0 and page.locator('#rf33-inspector').is_visible())
  check('material entry never mutates frozen garment observation',state()['observation']==original)
  page.set_viewport_size({'width':390,'height':844});page.evaluate('scrollTo(0,0)');page.wait_for_timeout(150);check('390px layout has no page overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth+2'));shot(page,'03-mobile-relations')
  check('no unhandled inspector errors',not report['pageErrors'],report['pageErrors']);check('no console errors',not report['consoleErrors'],report['consoleErrors']);check('no failed network requests',not report['failedRequests'],report['failedRequests'])
  report['passed']=True;report['fileVerified']=URL.startswith('file:');report['publicVerified']=URL.startswith('https:');report['countsByObject']={o['objectId']:o['counts'] for o in state()['bundle']['objects']}
 except Exception as e:
  report['failure']=str(e);report['trace']=traceback.format_exc();print(report['trace'],flush=True)
  try:report['lastState']=state();shot(page,'FAILURE')
  except Exception as e2:report['captureFailure']=str(e2)
 finally:save();context.close();browser.close()
if not report['passed']:raise SystemExit(1)
